import React, { useState } from 'react';

// Create ConfirmationDialog component here
function ConfirmationDialog(props) {
  // Initialize isOpen state here
  const [isOpen, setIsOpen] = useState(false);

  // Create openDialog handler here
  const openDialog = () => setIsOpen(true);

  // Create closeDialog handler here
  const closeDialog = () => setIsOpen(false);

  // Add conditional rendering here
  if (!isOpen) return null;

  // Display message in dialog
  return (
    <div>
      <p>{props.message}</p>
      {/* Add Confirm button here */}
      <button onClick={() => {
        props.onConfirm?.();
        closeDialog();
      }}>Confirm</button>
      {/* Add Cancel button here */}
    </div>
  );
}
